local M = _G.Evertally.map -- (Evertally_DungeonJournal: a module of Evertally_Map's pages since 2026-11-20)
-- Guides for the dungeons Forever took from Classic, levels 38 to 60. Written for Evertally from how these fights work in
-- Classic; `classic = true` makes the journal say so, since Forever may have changed a fight.
M.dungeonGuides = M.dungeonGuides or {}
local G = M.dungeonGuides
local function t(en, cs) return {en = en, cs = cs} end

G["Uldaman"] = {classic = true, mobs = {"humanoid", "mechanical", "giant", "beast"}, dispel = {"poison", "curse", "magic"},
    intro = t("A Titan vault in the Badlands, fought over by Dark Iron dwarves and troggs, with stone guardians deeper in. Long, with many quests.", "Titánský trezor v Badlands, o který bojují trpaslíci Dark Iron a troggové, hlouběji kamenní strážci. Dlouhý, s mnoha questy."),
    tips = {t("Many quests: collect them in Ironforge / Kargath and the Badlands before you go.", "Hodně questů: posbírejte je v Ironforge / Kargathu a v Badlands, než půjdete dovnitř."),
        t("The Obsidian Sentinel and the stone guardians need the Staff of Prehistoria / the platinum discs: read the quests' notes.", "K Obsidian Sentinelovi a kamenným strážcům je potřeba Staff of Prehistoria a platinové disky: čtěte poznámky questů.")},
    bosses = {Revelosh = t("A trogg caster with Chain Lightning: interrupt, spread.", "Trogg caster s Chain Lightning: přerušujte, roztáhněte se."),
        ["The Lost Dwarves"] = t("Three dwarves at once (Baelog, Eric, Olaf): crowd control one or two, kill them in turn.", "Tři trpaslíci naráz (Baelog, Eric, Olaf): jednoho nebo dva dejte do crowd controlu, zabíjejte postupně."),
        Ironaya = t("A stone keeper: Knock Away throws the tank, Arcing Smash hits around her front. Tank against a wall, everyone behind.", "Kamenná strážkyně: Knock Away odhodí tanka, Arcing Smash zasáhne před ní. Tank u zdi, ostatní za ní."),
        ["Obsidian Sentinel"] = t("Splits off Obsidian Shards as it takes damage: kill the shards before they reach the healer.", "Při zásazích se z něj odlupují Obsidian Shards: zabijte je dřív, než dojdou k healerovi."),
        ["Ancient Stone Keeper"] = t("Sand Storms move around the room: stay out of them.", "Po místnosti se pohybují Sand Storms: držte se mimo ně."),
        ["Galgann Firehammer"] = t("Fire Nova and Flame Shock: melee out of the nova, interrupt.", "Fire Nova a Flame Shock: melee mimo novu, přerušujte."),
        Grimlok = t("A trogg chief with lightning and a big basilisk add: kill or control the add.", "Trogg náčelník s bleskem a velkým baziliškem: přidaného zabijte nebo ovládněte."),
        Archaedas = t("Awakens stone guardians and earthen dwarves during the fight: area damage on the dwarves, the tank picks up the big guardians. Ground Tremor stuns around him.", "Během souboje probouzí kamenné strážce a trpaslíky: plošné poškození na trpaslíky, tank sebere velké strážce. Ground Tremor omráčí kolem něj.")}}

G["Zul'Farrak"] = {classic = true, mobs = {"humanoid", "undead", "beast"}, dispel = {"poison", "curse", "magic"},
    intro = t("A sandfury troll city in Tanaris. Open-air, with the famous stairs event: protect the freed prisoners while trolls rush up the pyramid.", "Město trollů Sandfury v Tanarisu. Pod širým nebem, se slavnou událostí na schodech: chraňte osvobozené vězně, zatímco trollové běží nahoru po pyramidě."),
    route = t("Antu'sul (basilisks) → Theka → Zum'rah and the graveyard → the pyramid stairs event (Sezz'ziz, Bly) → Velratha and Gahz'rilla (Mallet of Zul'Farrak) → Ukorz Sandscalp and Ruuzlu.", "Antu'sul (baziliškové) → Theka → Zum'rah a hřbitov → schody pyramidy (Sezz'ziz, Bly) → Velratha a Gahz'rilla (Mallet of Zul'Farrak) → Ukorz Sandscalp a Ruuzlu."),
    tips = {t("On the stairs, the group stands at the top and the tank holds the waves; area damage wins this event.", "Na schodech stojí skupina nahoře a tank drží vlny; tuhle událost vyhrává plošné poškození.")},
    bosses = {["Antu'sul"] = t("Summons basilisks and heals: kill the adds, interrupt the heal, then him.", "Vyvolává bazilišky a léčí se: zabijte přidané, přerušte léčení, pak jeho."),
        ["Theka the Martyr"] = t("Turns into a scarab and becomes immune to physical damage: casters finish him.", "Mění se ve skaraba a je imunní vůči fyzickému poškození: dorazte ho kouzly."),
        ["Witch Doctor Zum'rah"] = t("Raises zombies from the graves around: fight him away from the graves, area damage on the zombies.", "Vyvolává zombie z okolních hrobů: bojujte s ním dál od hrobů, plošné poškození na zombie."),
        ["Nekrum Gutchewer"] = t("Comes with the stairs waves: kill him with Sezz'ziz.", "Přichází s vlnami na schodech: zabijte ho spolu se Sezz'zizem."),
        ["Shadowpriest Sezz'ziz"] = t("Heals and Psychic Scream: interrupt the heals.", "Léčí a dává Psychic Scream: přerušujte léčení."),
        ["Sergeant Bly"] = t("After the stairs he and his crew turn on you if you do not talk first: be ready for four enemies at once.", "Po schodech se on a jeho parta obrátí proti vám: buďte připraveni na čtyři nepřátele naráz."),
        ["Hydromancer Velratha"] = t("Healing Wave and Frost Nova: interrupt the heals.", "Healing Wave a Frost Nova: přerušujte léčení."),
        ["Gahz'rilla"] = t("A hydra summoned with the Mallet: Freeze and Ice Nova, and Gahz'rilla Slam knocks into the air. Tank against a wall.", "Hydra přivolaná palicí: Freeze a Ice Nova, Gahz'rilla Slam vyhodí do vzduchu. Tank u zdi."),
        Ruuzlu = t("With Chief Ukorz: kill Ruuzlu first.", "S Chief Ukorzem: Ruuzlu zabijte první."),
        ["Chief Ukorz Sandscalp"] = t("Cleave and Wide Slash, enrages: melee behind him, tank faces him away.", "Cleave a Wide Slash, rozzuří se: melee za něj, tank ho otočí od skupiny.")}}

G["Maraudon"] = {classic = true, mobs = {"elemental", "beast", "humanoid", "giant"}, dispel = {"poison", "magic"},
    intro = t("Holy caves of the centaurs in Desolace, corrupted by Princess Theradras. Two outer wings (orange and purple) and the inner Earth Song Falls.", "Svaté jeskyně kentaurů v Desolace, zkažené princeznou Theradras. Dvě vnější křídla (oranžové a fialové) a vnitřní Earth Song Falls."),
    tips = {t("The Scepter of Celebras quest lets you port straight to the inner part later.", "Quest na Scepter of Celebras vám později umožní teleport rovnou dovnitř.")},
    bosses = {Noxxion = t("Splits into small adds and poisons: area damage on the adds, cure poison.", "Rozpadne se na malé přidané a otravuje: plošné poškození, čistěte jed."),
        Razorlash = t("Puncture and Cleave: melee behind.", "Puncture a Cleave: melee zezadu."),
        ["Lord Vyletongue"] = t("Blinks and Smoke Bomb, with satyr adds: kill the adds, stay close.", "Blink a Smoke Bomb, se satyry: zabijte přidané, držte se u něj."),
        ["Celebras the Cursed"] = t("Wrath and Entangling Roots, summons a tree: kill the tree, interrupt.", "Wrath a Entangling Roots, vyvolá strom: zabijte strom, přerušujte."),
        Landslide = t("An earth elemental: Knock Away, Trample, summons rock elementals at half health. Tank at a wall.", "Zemní elementál: Knock Away, Trample, na polovině vyvolá kamenné elementály. Tank u zdi."),
        ["Tinkerer Gizlock"] = t("A goblin with Goblin Dragon Gun and bombs: stay out of the front.", "Goblin s Goblin Dragon Gun a bombami: nestůjte před ním."),
        Rotgrip = t("A crocolisk in the water: Puncture on the tank.", "Krokodýl ve vodě: Puncture na tankovi."),
        ["Princess Theradras"] = t("Knock Away, Dust Field and Boulder: tank with the back to a wall, everyone else at range or behind, out of the dust.", "Knock Away, Dust Field a Boulder: tank zády ke zdi, ostatní zezadu nebo z dálky, mimo prach.")}}

G["Sunken Temple"] = {classic = true, mobs = {"humanoid", "dragonkin", "undead", "beast"}, dispel = {"poison", "disease", "curse", "magic"},
    intro = t("The Temple of Atal'Hakkar in the Swamp of Sorrows: Atal'ai trolls and green dragons of the Nightmare. Hard to find your way: the Altar bosses on the balconies open the way down.", "Chrám Atal'Hakkar v Swamp of Sorrows: trollové Atal'ai a zelení draci Noční můry. Snadno se v něm zabloudí: bossové u oltářů na balkonech otevírají cestu dolů."),
    route = t("Kill the six troll minibosses on the balconies (Gasher, Hukku, Loro, Mijan, Zolo, Zul'Lor) → Jammal'an and Ogom → the dragons (Morphaz and Hazzas, Dreamscythe and Weaver) → Shade of Eranikus. Atal'alarion and the Avatar of Hakkar are optional (statues / the Hakkar event).", "Zabijte šest trollích minibossů na balkonech (Gasher, Hukku, Loro, Mijan, Zolo, Zul'Lor) → Jammal'an a Ogom → draci (Morphaz a Hazzas, Dreamscythe a Weaver) → Shade of Eranikus. Atal'alarion a Avatar of Hakkar jsou volitelní (sochy / událost s Hakkarem)."),
    bosses = {["Altar Bosses"] = t("The six troll minibosses: each with a couple of adds, kill adds first.", "Šest trollích minibossů: každý má pár přidaných, ty jako první."),
        Gasher = t("A troll warrior: simple fight.", "Trollí válečník: jednoduchý souboj."),
        Hukku = t("Summons a voidwalker and imp: kill the pets.", "Vyvolá voidwalkera a impa: zabijte je."),
        Loro = t("Shield Bash and Thunderclap.", "Shield Bash a Thunderclap."),
        Mijan = t("Heals: interrupt.", "Léčí: přerušujte."),
        Zolo = t("Chain Lightning: spread.", "Chain Lightning: roztáhněte se."),
        ["Zul'Lor"] = t("Cleave: melee behind.", "Cleave: melee zezadu."),
        ["Atal'alarion"] = t("Summoned at the statues in the lower ring. Sweeping Slam knocks back: tank at a wall.", "Vyvolaný u soch v dolním kruhu. Sweeping Slam odhazuje: tank u zdi."),
        ["Morphaz & Hazzas"] = t("Two green dragons: breath in front and fear. Tank each facing away.", "Dva zelení draci: dech zepředu a strach. Tank je otočí od skupiny."),
        ["Jammal'an the Prophet"] = t("Hex turns a player into a frog and he heals: dispel, interrupt; Ogom comes with him.", "Hex promění hráče v žábu a léčí se: dispelujte, přerušujte; s ním je Ogom."),
        ["Ogom the Wretched"] = t("A shadow caster with Jammal'an: kill Jammal'an first.", "Stínový caster s Jammal'anem: Jammal'ana zabijte první."),
        ["Dreamscythe & Weaver"] = t("Two more green dragons: breath and Wing Flap, tank them away from the group.", "Další dva zelení draci: dech a Wing Flap, tank je otočí od skupiny."),
        ["Shade of Eranikus"] = t("Deep Slumber puts the group to sleep and War Stomp: dispel sleep, stay behind.", "Deep Slumber uspí skupinu a War Stomp: dispelujte spánek, stůjte zezadu."),
        ["Avatar of Hakkar"] = t("An event with blood: kill the Hakkari bloodkeepers to get the essence and use it on the brazier, then fight the Avatar (Curse of Tongues, Lash).", "Událost s krví: zabíjejte Hakkari bloodkeepery, esenci použijte u pánve, pak bojujte s Avatarem (Curse of Tongues, Lash).")}}

G["Blackrock Depths"] = {classic = true, mobs = {"humanoid", "elemental", "beast", "giant", "mechanical"}, dispel = {"poison", "curse", "magic"},
    intro = t("The Dark Iron city inside Blackrock Mountain: the biggest five-player dungeon, usually done in several runs (prison, arena, the Grim Guzzler, the throne room).", "Město Dark Iron uvnitř Blackrock Mountain: největší dungeon pro pět hráčů, obvykle se dělá na víc běhů (vězení, aréna, Grim Guzzler, trůnní sál)."),
    tips = {t("Pick a goal before you go (attunement, a quest, Emperor) and only clear what is on the way.", "Před vstupem si vyberte cíl (attunement, quest, Emperor) a čistěte jen to, co je po cestě."),
        t("Fire elementals and Dark Iron casters: fire resistance and interrupts help.", "Ohniví elementálové a castery Dark Iron: pomůže odolnost proti ohni a přerušování.")},
    bosses = {["High Interrogator Gerstahn"] = t("A shadow priest: Psychic Scream and Shadow Word: Pain. Tank at a wall.", "Stínová kněžka: Psychic Scream a Shadow Word: Pain. Tank u zdi."),
        ["Lord Roccor"] = t("A fire elemental: Earth Shock and Flame Shock. Interrupt.", "Ohnivý elementál: Earth Shock a Flame Shock. Přerušujte."),
        ["Houndmaster Grebmar"] = t("With his dogs, enrages: kill the dogs.", "Se psy, rozzuří se: zabijte psy."),
        ["Gorosh the Dervish"] = t("Arena: Whirlwind, melee out.", "Aréna: Whirlwind, melee pryč."),
        Grizzle = t("Arena: Thunderclap and enrage.", "Aréna: Thunderclap a rozzuření."),
        Eviscerator = t("Arena: shadow-reflecting shield, use physical damage.", "Aréna: štít odrážející stínovou magii, použijte fyzické poškození."),
        ["Ok'thor the Breaker"] = t("Arena: arcane caster, interrupt.", "Aréna: arkánový caster, přerušujte."),
        ["Anub'shiah"] = t("Arena: Curse of Tongues and Enveloping Web, remove the curse.", "Aréna: Curse of Tongues a Enveloping Web, čistěte kletbu."),
        ["Hedrum the Creeper"] = t("Arena: a spider with poison, cure it.", "Aréna: pavouk s jedem, čistěte ho."),
        ["Pyromancer Loregrain"] = t("Fire caster with a totem: kill the totem, interrupt.", "Ohnivý caster s totemem: zničte totem, přerušujte."),
        ["Fineous Darkvire"] = t("Heals himself: interrupt.", "Léčí se: přerušujte."),
        ["Warder Stilgiss"] = t("Frost caster with Verek (a dog): kill the dog or control it.", "Ledový caster s Verekem (pes): psa zabijte nebo ovládněte."),
        ["Secret Safe"] = t("A vault event: opening it releases waves of guards.", "Událost s trezorem: otevření vypustí vlny stráží."),
        ["Lord Incendius"] = t("Fire elemental: Fire Storm and Mighty Blow. Fire resistance, tank at a wall.", "Ohnivý elementál: Fire Storm a Mighty Blow. Odolnost proti ohni, tank u zdi."),
        ["Bael'Gar"] = t("A giant fire elemental that summons Lava Spawns: kill the spawns before they split.", "Obří ohnivý elementál, vyvolává Lava Spawny: zabijte je, než se rozdělí."),
        ["General Angerforge"] = t("Calls guards at low health: save cooldowns, kill him fast at the end.", "Na nízkém zdraví volá stráže: šetřete cooldowny, na konci ho rychle dorazte."),
        ["Golem Lord Argelmach"] = t("Wakes golems around him: clear the golems first, interrupt his Chain Lightning.", "Probouzí golemy kolem sebe: golemy vyčistěte předem, přerušujte jeho Chain Lightning."),
        ["Hurley Blackbreath"] = t("Grim Guzzler: comes with guards after the ale event.", "Grim Guzzler: přijde se strážemi po události s pivem."),
        Phalanx = t("Grim Guzzler: a huge golem, tank and spank.", "Grim Guzzler: obrovský golem, jednoduchý souboj."),
        ["Ribbly Screwspigot"] = t("Grim Guzzler: a goblin with friends.", "Grim Guzzler: goblin s kamarády."),
        ["Plugger Spazzring"] = t("Grim Guzzler: stealing the ale turns the whole bar hostile; be ready.", "Grim Guzzler: krádež piva poštve celý bar; buďte připraveni."),
        ["Ambassador Flamelash"] = t("Fire elemental adds walk to him from the runes: kill them on the way.", "Od run k němu jdou ohniví elementálové: zabíjejte je cestou."),
        ["The Seven"] = t("Seven dwarf spirits one after another (Doom'rel's event): each has its own trick; take a break between them.", "Sedm trpasličích duchů po sobě (událost Doom'rela): každý má jiný trik; mezi nimi si odpočiňte."),
        Magmus = t("A giant at the throne room door; fire jets from the walls: stay out of them.", "Obr u dveří trůnního sálu; ze zdí tryská oheň: držte se mimo."),
        ["Princess Moira Bronzebeard"] = t("A healer next to the Emperor: interrupt her or crowd control her. Killing her fails the Alliance quest.", "Léčitelka vedle císaře: přerušujte ji nebo ovládněte. Její zabití pokazí questy Aliance."),
        ["Emperor Dagran Thaurissan"] = t("Hand of Thaurissan stuns and Avatar of Flame: tank cooldowns, interrupt Moira's heals.", "Hand of Thaurissan omráčí a Avatar of Flame: cooldowny tanka, přerušujte Moiřino léčení.")}}

G["Dire Maul: East"] = {classic = true, mobs = {"demon", "beast", "elemental"}, dispel = {"poison", "magic"},
    intro = t("The overgrown east wing of the ancient city in Feralas: satyrs, treants and Alzzin the Wildshaper.", "Zarostlé východní křídlo starého města ve Feralasu: satyrové, stromoví lidé a Alzzin the Wildshaper."),
    bosses = {Pusillin = t("An imp you chase through the wing; he fights at the end with imp adds.", "Imp, kterého honíte křídlem; na konci bojuje s impy."),
        ["Zevrim Thornhoof"] = t("Sacrifice drains a player's health: heal the target.", "Sacrifice vysává hráči zdraví: léčte cíl."),
        Hydrospawn = t("A water elemental: Massive Geyser throws players up, avoid falling.", "Vodní elementál: Massive Geyser vyhodí hráče, pozor na pád."),
        Lethtendris = t("Shadow caster with an add: interrupt.", "Stínový caster s přidaným: přerušujte."),
        ["Alzzin the Wildshaper"] = t("Changes shapes and summons wildspawns: area damage on the adds.", "Mění podobu a vyvolává divoké potvory: plošné poškození na přidané.")}}

G["Dire Maul: West"] = {classic = true, mobs = {"undead", "demon", "humanoid"}, dispel = {"curse", "magic"},
    intro = t("The Shen'dralar wing: Highborne ghosts, the pylons around Immol'thar and Prince Tortheldrin.", "Křídlo Shen'dralar: duchové Highborne, pylony kolem Immol'thara a princ Tortheldrin."),
    bosses = {["Tendris Warpwood"] = t("An ancient with treant adds: kill the adds.", "Prastarý strom s přidanými: zabijte je."),
        ["Magister Kalendris"] = t("Shadow caster, Mind Blast: interrupt.", "Stínový caster, Mind Blast: přerušujte."),
        ["Illyanna Ravenoak"] = t("A hunter with a pet bear: kill the pet or control it.", "Lovkyně s medvědem: medvěda zabijte nebo ovládněte."),
        ["Immol'thar"] = t("Destroy the five pylons to free him. Summons eyes and Trample: kill the eyes, tank at a wall.", "Zničte pět pylonů, tím ho uvolníte. Vyvolává oči a Trample: oči zabijte, tank u zdi."),
        ["Lord Hel'nurath"] = t("A summoned demon (warlock epic mount quest): fear and shadow.", "Vyvolaný démon (warlockův quest na epického koně): strach a stín."),
        ["Prince Tortheldrin"] = t("Whirlwind and Counterspell: melee out of the whirlwind.", "Whirlwind a Counterspell: melee mimo whirlwind.")}}

G["Dire Maul: North"] = {classic = true, mobs = {"giant", "humanoid"}, dispel = {"magic"},
    intro = t("The Gordok ogres' wing. The tribute run: kill the bosses but leave the guards alive (and do not kill Knot Thimblejack) for the best tribute chest.", "Křídlo zlobrů Gordok. Tribute run: zabijte bosse, ale nechte žít stráže (a nezabíjejte Knota Thimblejacka) a dostanete nejlepší truhlu."),
    tips = {t("Ogres hit hard and are humanoids: traps, saps and sheep.", "Zlobři tvrdě bijí a jsou humanoidi: pasti, sapy a ovce.")},
    bosses = {["Guard Mol'dar"] = t("Leave him alive for the tribute; otherwise a simple fight.", "Kvůli truhle ho nechte naživu; jinak jednoduchý souboj."),
        ["Stomper Kreeg"] = t("Drunk ogre with Whirlwind; leave alive for the tribute.", "Opilý zlobr s Whirlwindem; kvůli truhle nechte naživu."),
        ["Guard Fengus"] = t("Leave alive for the tribute.", "Kvůli truhle nechte naživu."),
        ["Guard Slip'kik"] = t("Freeze him with a Frost Trap (hunter) to pass for the tribute.", "Kvůli truhle ho projděte zmražením (hunterova Frost Trap)."),
        ["Captain Kromcrush"] = t("Summons guards; leave alive for the tribute.", "Volá stráže; kvůli truhle nechte naživu."),
        ["Cho'Rush the Observer"] = t("A caster ogre next to the king: kill him first.", "Zlobří caster vedle krále: zabijte ho první."),
        ["King Gordok"] = t("Mortal Strike on the tank: heal through, then talk to Cho'Rush for the tribute.", "Mortal Strike na tanka: proléčit, pak promluvte s Cho'Rushem kvůli truhle."),
        ["Gordok Tribute Chest"] = t("The chest after the king: the more guards alive, the better.", "Truhla po králi: čím víc stráží naživu, tím lepší."),
        ["Knot Thimblejack's Cache"] = t("Free Knot (do not kill him) for his cache.", "Osvoboďte Knota (nezabíjejte ho) kvůli jeho skrýši.")}}

G["Lower Blackrock Spire"] = {classic = true, mobs = {"humanoid", "giant", "beast", "dragonkin"}, dispel = {"poison", "disease", "curse"},
    intro = t("The orc-held lower spire of Blackrock: ogres, orcs and spiders; on the way to the Upper Spire key (Seal of Ascension).", "Spodní část Blackrock Spire v rukou orků: zlobři, orkové a pavouci; po cestě ke klíči do horní části (Seal of Ascension)."),
    bosses = {["Highlord Omokk"] = t("A huge ogre: Knock Away. Tank at a wall.", "Obrovský zlobr: Knock Away. Tank u zdi."),
        ["Shadow Hunter Vosh'gajin"] = t("Hex and Curse of Blood: dispel and remove curses.", "Hex a Curse of Blood: dispelujte a čistěte kletby."),
        ["War Master Voone"] = t("Throws axes and Mortal Strike: heal through.", "Hází sekery a Mortal Strike: proléčit."),
        ["Mother Smolderweb"] = t("A spider with Crystallize (stun) and poison: cure poison.", "Pavoučice s Crystallize (omráčení) a jedem: čistěte jed."),
        ["Urok Doomhowl"] = t("A challenge event with waves of ogres: tank gathers them.", "Událost s vlnami zlobrů: tank je sbírá."),
        ["Quartermaster Zigris"] = t("Drinks potions, shoots: stay close.", "Pije lektvary, střílí: držte se u něj."),
        Halycon = t("A worg: Rend and Thrash.", "Vlk: Rend a Thrash."),
        ["Gizrul the Slavener"] = t("Comes after Halycon: enrages, Fatal Bite.", "Přijde po Halycon: rozzuří se, Fatal Bite."),
        ["Overlord Wyrmthalak"] = t("Calls two adds at half health: tank picks them up, kill the adds.", "Na polovině zavolá dva přidané: tank je sebere, zabijte je.")}}

G["Upper Blackrock Spire"] = {classic = true, mobs = {"humanoid", "dragonkin", "beast"}, dispel = {"poison", "curse", "magic"},
    intro = t("The black dragonflight's upper spire, home of General Drakkisath. Ten-player in Classic; Forever lists it among the dungeons: check the group size it asks for.", "Horní část věže černého dračího hejna, sídlo generála Drakkisatha. V Classicu pro deset hráčů; Forever ji uvádí mezi dungeony: ověř si velikost skupiny."),
    bosses = {["Pyroguard Emberseer"] = t("Kill the incarcerators around him to release him: then Fire Nova and Flamestrike.", "Uvolněte ho zabitím strážců kolem: pak Fire Nova a Flamestrike."),
        ["Solakar Flamewreath"] = t("Hatchery event: break eggs carefully, waves of whelps and handlers come.", "Událost v líhni: pozor na vejce, přichází vlny dráčat a jejich strážců."),
